def test_mpax_survives_missing_jax(self):
    import sys
    import importlib

    # Preserve any existing jax modules
    saved_modules = {name: sys.modules[name] for name in list(sys.modules) if name.startswith("jax")}

    # Remove jax and its submodules from sys.modules to simulate missing JAX
    for name in list(sys.modules):
        if name.startswith("jax"):
            del sys.modules[name]

    try:
        # Import the module under test; it should not raise even though JAX is absent
        mpax_if = importlib.import_module("mpax_if")
        # When JAX is unavailable, the module should expose a None placeholder
        self.assertIsNone(getattr(mpax_if, "jax", None))
    finally:
        # Restore the original jax modules to avoid side‑effects for other tests
        for name, module in saved_modules.items():
            sys.modules[name] = module

def test_mpax_survives_missing_jax(self):
    import sys
    import importlib

    # Preserve any existing jax related modules
    saved_modules = {}
    for mod_name in ("jax", "jax.numpy"):
        if mod_name in sys.modules:
            saved_modules[mod_name] = sys.modules[mod_name]
            del sys.modules[mod_name]

    # Ensure mpax_if is not already loaded
    if "mpax_if" in sys.modules:
        del sys.modules["mpax_if"]

    try:
        # Import the module; it should not raise even though jax is absent
        mpax_if = importlib.import_module("mpax_if")
        # The module should still expose MPAX_ctx (even if jax is None)
        self.assertTrue(hasattr(mpax_if, "MPAX_ctx"))
        # When jax is missing, the internal jax reference should be None
        self.assertTrue(getattr(mpax_if, "jax", None) is None)
    finally:
        # Restore original modules
        for name, mod in saved_modules.items():
            sys.modules[name] = mod
        # Reload mpax_if to reset its state for subsequent tests
        if "mpax_if" in sys.modules:
            importlib.reload(sys.modules["mpax_if"])

def should_use_curvature(self, max_chain_length: int) -> bool:
    """Determine if curvature features should be used.

    Curvature calculations require at least three points in a chain.
    """
    if not isinstance(max_chain_length, int):
        raise TypeError("max_chain_length must be an integer")
    if max_chain_length < 0:
        raise ValueError("max_chain_length must be non‑negative")
    return max_chain_length >= 3

