def _get_remote_config_by_id(self, config_id: str) -> Optional[RemoteContentConfig]:
    """Retrieve a RemoteContentConfig instance matching the given ``config_id``.

    Returns ``None`` if the identifier is empty or no matching configuration is
    found.
    """
    if not config_id:
        return None

    # Primary storage: a dict mapping IDs to configs.
    config_map = getattr(self, "_remote_content_configs", None)
    if isinstance(config_map, dict):
        return config_map.get(config_id)

    # Fallback: iterate over a list/iterable of configs.
    for cfg in getattr(self, "remote_content_configs", []):
        if getattr(cfg, "id", None) == config_id:
            return cfg

    return None

def _get_remote_config_by_id(self, config_id: str) -> Optional[RemoteContentConfig]:
    """Return the remote content configuration matching ``config_id``.

    The underlying storage may be a dict mapping IDs to ``RemoteContentConfig`` or
    an iterable of such objects.  If the configuration cannot be found, ``None`` is
    returned.
    """
    # Fast path: dict‑like storage
    try:
        return self.remote_content_configs[config_id]  # type: ignore[index]
    except (KeyError, TypeError, AttributeError):
        pass

    # Fallback: iterate over an iterable of configs
    for cfg in getattr(self, "remote_content_configs", []):
        if getattr(cfg, "id", None) == config_id:
            return cfg

    return None

def _get_remote_config_by_id(self, config_id: str) -> Optional[RemoteContentConfig]:
    """
    Retrieve a remote content configuration by its unique identifier.

    Args:
        config_id: The identifier of the remote content configuration.

    Returns:
        The matching ``RemoteContentConfig`` instance if found, otherwise ``None``.
    """
    # If the configs are stored in a dict keyed by ID, use direct lookup.
    if isinstance(getattr(self, "remote_content_configs", None), dict):
        return self.remote_content_configs.get(config_id)

    # Fallback to iterating over a list or other iterable collection.
    for cfg in getattr(self, "remote_content_configs", []):
        if getattr(cfg, "id", None) == config_id:
            return cfg
    return None

