def dict(self, **kwargs: Any) -> Dict[str, Any]:
    """
    Override the default dict method to `exclude_unset` by default. This function patches
    `exclude_unset` to work include fields within non-None default values.
    """
    # Note: the logic here is multi-plexed given the levers exposed in Pydantic V1 vs V2
    # Pydantic V1's .dict can be extremely slow, so we do not want to call it twice.
    #
    # We'd ideally do the same for Pydantic V2, but it shells out to a library to serialize models
    # that we have less control over, and this is less intrusive than custom serializers for now.
    if IS_PYDANTIC_V2:
        kwargs_with_defaults_exclude_unset = {
            **kwargs,
            "by_alias": True,
            "exclude_unset": True,
            "exclude_none": False,
        }
        kwargs_with_defaults_exclude_none = {
            **kwargs,
            "by_alias": True,
            "exclude_none": True,
            "exclude_unset": False,
        }
        dict_dump = deep_union_pydantic_dicts(
            super().dict(**kwargs_with_defaults_exclude_unset),  # type: ignore[misc]
            super().dict(**kwargs_with_defaults_exclude_none),  # type: ignore[misc]
        )

    else:
        _fields_set = self.__fields_set__.copy()

        fields = _get_model_fields(self.__class__)
        for name, field in fields.items():
            if name not in _fields_set:
                default = _get_field_default(field)

                # If the default values are non-null act like they've been set
                # This effectively allows exclude_unset to work like exclude_none where
                # the latter passes through intentionally set none values.
                if default is not None or ("exclude_unset" in kwargs and not kwargs["exclude_unset"]):
                    _fields_set.add(name)

                    if default is not None:
                        self.__fields_set__.add(name)

        kwargs_with_defaults_exclude_unset_include_fields = {
            "by_alias": True,
            "exclude_unset": True,
            "include": _fields_set,
            **kwargs,
        }

        dict_dump = super().dict(**kwargs_with_defaults_exclude_unset_include_fields)  # type: ignore[misc]

    return convert_and_respect_annotation_metadata(object_=dict_dump, annotation=self.__class__, direction="read")

