def dict(self, **kwargs: Any) -> Dict[str, Any]:
    """
    Override BaseModel.dict to default ``exclude_unset`` to ``True`` and ensure that
    fields with a non‑``None`` default value are still included even when they are
    considered unset.

    The function respects any explicit ``exclude_unset`` value passed in ``kwargs``.
    When ``exclude_unset`` is ``True``, it builds an ``include`` set containing
    fields whose default is not ``None`` and that have not been explicitly set on
    the model instance. This ``include`` set is merged with any user‑provided
    ``include`` argument before delegating to ``BaseModel.dict``.
    """
    # Default to excluding unset fields unless the caller overrides it.
    if "exclude_unset" not in kwargs:
        kwargs["exclude_unset"] = True

    # If we are excluding unset fields, make sure we still emit fields that have
    # a non‑None default value even when they are not present in ``__fields_set``.
    if kwargs.get("exclude_unset"):
        # Determine which fields have a non‑None default and are currently unset.
        default_includes = {
            name
            for name, field in self.__fields__.items()
            if field.default is not None and name not in self.__fields_set
        }

        # Merge with any user‑provided ``include`` argument.
        user_include = kwargs.get("include")
        if user_include:
            if isinstance(user_include, (set, frozenset)):
                default_includes.update(user_include)
            elif isinstance(user_include, dict):
                default_includes.update(user_include.keys())
            else:
                # Assume an iterable of field names.
                default_includes.update(set(user_include))

        kwargs["include"] = default_includes

    return super().dict(**kwargs)

def _output_via_wtype(text: str, config) -> bool:
    """
    Output text using wtype (Wayland).

    Args:
        text: The text to type.
        config: Configuration object (expects a ``logger`` attribute).

    Returns:
        True if successful, False otherwise.
    """
    import shutil
    import subprocess

    try:
        # Locate the wtype executable
        wtype_path = shutil.which("wtype")
        if not wtype_path:
            if hasattr(config, "logger"):
                config.logger.debug("wtype executable not found in PATH.")
            return False

        # Execute wtype with the provided text
        result = subprocess.run(
            [wtype_path, text],
            capture_output=True,
            text=True,
        )

        if result.returncode == 0:
            if hasattr(config, "logger"):
                config.logger.debug(f"Successfully typed via wtype: {text!r}")
            return True
        else:
            if hasattr(config, "logger"):
                config.logger.debug(
                    f"wtype returned non-zero exit status {result.returncode}: {result.stderr.strip()}"
                )
            return False

    except Exception as exc:
        if hasattr(config, "logger"):
            config.logger.exception(f"Exception while invoking wtype: {exc}")
        return False

