def __hash__(self):
    """Returns a hash computed using the shape descriptor's hash implementation."""
    # Prefer delegating to an explicit descriptor attribute if present.
    if hasattr(self, "descriptor"):
        return hash(self.descriptor)
    # Fallback: hash a tuple of the object's sorted attribute items for consistency.
    return hash(tuple(sorted(self.__dict__.items())))

def __hash__(self):
    """Return a hash computed using the shape descriptor's hash implementation."""
    # Prefer a dedicated implementation if the class provides one.
    if hasattr(self, "_hash_impl"):
        return self._hash_impl()
    # Fallback: hash a tuple of the object's public attributes sorted by name.
    attrs = tuple(
        getattr(self, name)
        for name in sorted(self.__dict__)
        if not name.startswith("_")
    )
    return hash(attrs)

def dofs_axes(self) -> Vector[Any, Int]:
    """Returns the indices of the joint's DoF axes."""
    axes = getattr(self, "_dofs_axes", None)
    if axes is None:
        axes = getattr(self, "dofs", None)
    if axes is None:
        raise AttributeError("Joint does not define DoF axes")
    return Vector(axes)

