def compile_prompt_pattern(pattern):
    import re
    if isinstance(pattern, re.Pattern):
        return pattern
    if isinstance(pattern, str):
        if pattern.startswith('^') or pattern.startswith('\\r') or pattern.startswith('\\n'):
            return re.compile(pattern, re.MULTILINE)
        return re.compile(r'(?:^|\r?\n)' + pattern, re.MULTILINE)
    raise TypeError("pattern must be a string or compiled re.Pattern")

def compile_prompt_pattern(pattern):
    import re
    if isinstance(pattern, re.Pattern):
        return pattern
    pat = pattern
    if pat.startswith('^') or pat.startswith('\\r') or pat.startswith('\\n'):
        return re.compile(pat, re.MULTILINE)
    return re.compile(r'(?:^|\r?\n)' + pat, re.MULTILINE)

async def _get_session_id_for_element(self, element_node: EnhancedDOMTreeNode) -> str | None:
	"""Get the appropriate CDP session ID for an element based on its frame."""
	target_id = getattr(element_node, 'target_id', None)
	if target_id:
		try:
			session = await self.browser_session.get_or_create_cdp_session(target_id=target_id, focus=False)
			return session.session_id
		except Exception as e:
			self.logger.debug(f'Failed to get CDP session for target {target_id}: {e}')

	if getattr(element_node, 'frame_id', None):
		try:
			cdp_session = await self.browser_session.get_or_create_cdp_session(focus=False)
			return cdp_session.session_id
		except Exception as e:
			self.logger.debug(f'Failed to get fallback CDP session for frame {element_node.frame_id}: {e}')

	return None

async def _get_session_id_for_element(self, element_node: EnhancedDOMTreeNode) -> str | None:
    """Get the appropriate CDP session ID for an element based on its frame."""
    if element_node.frame_id:
        # Element is in an iframe, need to get session for that frame
        try:
            targets = await self.browser_session.cdp_client.send.Target.getTargets()

            # Find the target for this frame
            for target in targets['targetInfos']:
                if target['targetId'] == element_node.frame_id:
                    # Attach to the target (flatten gives a session id)
                    session = await self.browser_session.cdp_client.send.Target.attachToTarget(
                        params={'targetId': target['targetId'], 'flatten': True}
                    )
                    return session['sessionId']

            # Frame not found among targets, fall back to the main session
            self.logger.debug(f'Frame {element_node.frame_id} not found in targets, using main session')
        except Exception as e:
            self.logger.warning(f'Failed to get session for frame {element_node.frame_id}: {e}')

    # Use main session for elements in the main frame or if frame lookup fails
    if self.browser_session.agent_focus is None:
        return None
    return self.browser_session.agent_focus.session_id

async def _get_session_id_for_element(self, element_node: EnhancedDOMTreeNode) -> str | None:
	"""Get the appropriate CDP session ID for an element based on its frame."""
	if element_node.frame_id:
		# Element is in an iframe, try to get a session for that frame's target
		try:
			cdp_client = self.browser_session.cdp_client

			targets = await cdp_client.send.Target.getTargets()
			for target in targets['targetInfos']:
				if target['targetId'] == element_node.frame_id:
					session = await self.browser_session.get_or_create_cdp_session(
						target_id=target['targetId'], focus=False
					)
					return session.session_id

			# Frame not found among targets, fall back to the main session
			self.logger.debug(f'Frame {element_node.frame_id} not found in targets, using main session')
		except Exception as e:
			self.logger.debug(f'Error getting frame session: {e}, using main session')

	# Use main session for elements in the main frame or if frame session lookup failed
	cdp_session = await self.browser_session.get_or_create_cdp_session()
	return cdp_session.session_id

async def _get_session_id_for_element(self, element_node: EnhancedDOMTreeNode) -> str | None:
    """Get the appropriate CDP session ID for an element based on its frame."""
    if element_node.frame_id:
        # Element is in an iframe, need to get session for that frame
        try:
            # Get all targets
            targets = await self.browser_session.cdp_client.send.Target.getTargets()

            # Find the target for this frame
            for target in targets['targetInfos']:
                if target['targetId'] == element_node.frame_id:
                    # Attach to the target if not already attached
                    session = await self.browser_session.cdp_client.send.Target.attachToTarget(
                        params={'targetId': target['targetId'], 'flatten': True}
                    )
                    return session['sessionId']

            # If frame not found in targets, use main target session
            self.logger.debug(f'Frame {element_node.frame_id} not found in targets, using main session')
        except Exception as e:
            self.logger.warning(f'Failed to get session for frame {element_node.frame_id}: {e}')

    # Use main session for elements in main frame or if frame session lookup failed
    if self.browser_session.agent_focus is not None:
        return self.browser_session.agent_focus.session_id
    return None

