def _boundary_values(boundaries, min_val, max_val, step=1, width=5, sparse_count=100):
  """Generate test values dense around boundaries and sparse across the full range.

  For threshold-style safety checks, exhaustively testing every value is wasteful.
  This generates values ±width*step around each boundary, plus sparse sampling.
  """
  values = set()

  def add(v):
    if min_val <= v <= max_val:
      if isinstance(step, int) and isinstance(v, float) and v.is_integer():
        v = int(v)
      values.add(v)

  # dense values around each boundary
  for b in boundaries:
    for i in range(-width, width + 1):
      add(b + i * step)

  # always include range endpoints
  add(min_val)
  add(max_val)

  # sparse sampling across the full range
  if sparse_count > 0 and max_val > min_val:
    span = max_val - min_val
    n_steps = int(span / step)
    if n_steps <= 0:
      n_steps = 1
    stride = max(1, n_steps // sparse_count)
    i = 0
    while i <= n_steps:
      add(min_val + i * step)
      i += stride

  return sorted(values)

def _boundary_values(boundaries, min_val, max_val, step=1, width=5, sparse_count=100):
  """Generate test values dense around boundaries and sparse across the full range.

  For threshold-style safety checks, exhaustively testing every value is wasteful.
  This generates values ±width*step around each boundary, plus sparse sampling.
  """
  values = set()

  # Dense values around each boundary
  for b in boundaries:
    for i in range(-width, width + 1):
      v = b + i * step
      if min_val <= v <= max_val:
        values.add(v)

  # Always include range endpoints
  values.add(min_val)
  values.add(max_val)

  # Sparse sampling across the full range
  if sparse_count > 1 and max_val > min_val:
    span = max_val - min_val
    for i in range(sparse_count):
      v = min_val + span * i / (sparse_count - 1)
      if isinstance(step, int) and isinstance(min_val, int):
        v = int(round(v))
      else:
        # snap to step grid relative to min_val for floats
        v = min_val + round((v - min_val) / step) * step
      if min_val <= v <= max_val:
        values.add(v)

  return sorted(values)

def _boundary_values(boundaries, min_val, max_val, step=1, width=5, sparse_count=100):
    """Generate test values dense around boundaries and sparse across the full range."""
    values = set()

