            if min_val <= v <= max_val:
                values.add(v)

    # Sparse sampling across the whole range
    if sparse_count > 0:
        if sparse_count == 1:
            values.add(min_val)
        else:
            interval = (max_val - min_val) / (sparse_count - 1)
            for i in range(sparse_count):
                v = min_val + i * interval
                if min_val <= v <= max_val:
