def _find_def_line(self, lines: List[str], function_name: str) -> Optional[int]:
    import re
    pattern = re.compile(r'^\s*def\s+%s\s*\(' % re.escape(function_name))
    for idx, line in enumerate(lines):
        if pattern.match(line):
            return idx
    return None

