def test_benchmark_block_table_to_ragged(max_batch_size, max_blocks_per_seq):
    import time

    import pytest
    import torch

    if not torch.cuda.is_available():
        pytest.skip("CUDA is required for the block_table -> ragged benchmark")

    device = "cuda"
    torch.manual_seed(0)

    num_pages_per_seq = torch.randint(
        1, max_blocks_per_seq + 1, (max_batch_size,), device=device, dtype=torch.int32
    )
    block_table = torch.randint(
        0,
        max_batch_size * max_blocks_per_seq,
        (max_batch_size, max_blocks_per_seq),
        device=device,
        dtype=torch.int32,
    )
    cu_num_pages = torch.zeros(max_batch_size + 1, device=device, dtype=torch.int32)
    cu_num_pages[1:] = torch.cumsum(num_pages_per_seq, dim=0)

    def torch_block_table_to_ragged():
        col_idx = torch.arange(max_blocks_per_seq, device=device, dtype=torch.int32)
        mask = col_idx[None, :] < num_pages_per_seq[:, None]
        return block_table[mask]

    def time_fn(fn, warmup=5, iters=50):
        for _ in range(warmup):
            fn()
        torch.cuda.synchronize()
        start = time.perf_counter()
        for _ in range(iters):
            fn()
        torch.cuda.synchronize()
        return (time.perf_counter() - start) / iters * 1e3

    ref = torch_block_table_to_ragged()
    assert ref.numel() == int(cu_num_pages[-1].item())

    torch_ms = time_fn(torch_block_table_to_ragged)
    results = {"torch_ms": torch_ms}

    try:
        from tensorrt_llm._torch.auto_deploy.custom_ops.utils.block_table_ragged import (
            block_table_to_ragged as triton_block_table_to_ragged,
        )
    except ImportError:
        triton_block_table_to_ragged = None

    if triton_block_table_to_ragged is not None:

        def triton_fn():
            return triton_block_table_to_ragged(block_table, num_pages_per_seq, cu_num_pages)

        out = triton_fn()
        torch.cuda.synchronize()
        assert torch.equal(out.flatten()[: ref.numel()], ref.flatten())
        results["triton_ms"] = time_fn(triton_fn)
        results["speedup"] = torch_ms / results["triton_ms"]

    print(
        f"\nblock_table->ragged [bs={max_batch_size}, max_blocks={max_blocks_per_seq}, "
        f"total_pages={ref.numel()}]: "
        + ", ".join(f"{k}={v:.4f}" for k, v in results.items())
    )
