    """Benchmark block_table -> ragged: Triton vs PyTorch."""
    import torch

    if not torch.cuda.is_available():
        pytest.skip("CUDA required")

    from tensorrt_llm._torch.auto_deploy.custom_ops.utils.block_table_ragged import (
        block_table_to_ragged,
    )

    device = "cuda"
    torch.manual_seed(0)

    num_pages = torch.randint(
        1, max_blocks_per_seq + 1, (max_batch_size,), device=device, dtype=torch.int32
    )
    cu_num_pages = torch.zeros(max_batch_size + 1, device=device, dtype=torch.int32)
    cu_num_pages[1:] = torch.cumsum(num_pages, dim=0)
    block_table = torch.randint(
        0, 100000, (max_batch_size, max_blocks_per_seq), device=device, dtype=torch.int32
    )

    def pytorch_impl():
        counts = (cu_num_pages[1:] - cu_num_pages[:-1]).long()
        total = int(cu_num_pages[-1].item())
        row_idx = torch.repeat_interleave(
            torch.arange(max_batch_size, device=device), counts, output_size=total
        )
        offsets = torch.arange(total, device=device) - cu_num_pages[:-1].long()[row_idx]
        return block_table[row_idx, offsets]

    def triton_impl():
        return block_table_to_ragged(block_table, cu_num_pages)

    # correctness check
    ref = pytorch_impl()
    out = triton_impl()
    total = int(cu_num_pages[-1].item())
    torch.testing.assert_close(out[:total].to(ref.dtype), ref)

