@pytest.mark.skipif(not torch.cuda.is_available(), reason="CUDA required")
@pytest.mark.parametrize("max_batch_size", [8, 64, 256])
@pytest.mark.parametrize("max_blocks_per_seq", [16, 128, 512])
def test_benchmark_block_table_to_ragged(max_batch_size, max_blocks_per_seq):
    """Benchmark block_table -> ragged: Triton vs PyTorch."""
    from tensorrt_llm._torch.auto_deploy.custom_ops.utils.block_table_ragged import (
        block_table_to_ragged,
    )

    device = "cuda"
    torch.manual_seed(0)

    num_pages = torch.randint(
        1, max_blocks_per_seq + 1, (max_batch_size,), device=device, dtype=torch.int32
    )
    cu_num_pages = torch.zeros(max_batch_size + 1, device=device, dtype=torch.int32)
    cu_num_pages[1:] = torch.cumsum(num_pages, dim=0)
    block_table = torch.randint(
        0, 100000, (max_batch_size, max_blocks_per_seq), device=device, dtype=torch.int32
    )

    def pytorch_impl():
        pieces = [block_table[i, : int(num_pages[i].item())] for i in range(max_batch_size)]
        return torch.cat(pieces)

    def triton_impl():
        out = block_table_to_ragged(block_table, cu_num_pages)
        if isinstance(out, (tuple, list)):
            out = out[0]
        return out

    # correctness
    ref = pytorch_impl()
    res = triton_impl()
    total = int(cu_num_pages[-1].item())
    torch.testing.assert_close(res[:total].to(ref.dtype), ref)

    def bench(fn, warmup=10, iters=50):
        for _ in range(warmup):
            fn()
        torch.cuda.synchronize()
        start = torch.cuda.Event(enable_timing=True)
        end = torch.cuda.Event(enable_timing=True)
        start.record()
        for _ in range(iters):
            fn()
        end.record()
        torch.cuda.synchronize()
        return start.elapsed_time(end) / iters

    t_triton = bench(triton_impl)
    t_torch = bench(pytorch_impl)

    print(
        f"\n[block_table -> ragged] batch={max_batch_size} blocks/seq={max_blocks_per_seq}: "
        f"triton={t_triton:.4f} ms, pytorch={t_torch:.4f} ms, "
        f"speedup={t_torch / max(t_triton, 1e-9):.2f}x"
    )

def grep_count_files(name: str, file_list: list[str], *, word_boundary: bool = True, encoding: str = "utf-8", errors: str = "ignore") -> list[str]:
    """Return list of files containing name. Replacement for ``grep -rl -w name``."""
    import re

    pattern = re.escape(name)
    if word_boundary:
        pattern = rf"(?<!\w){pattern}(?!\w)"
    regex = re.compile(pattern)

    matches: list[str] = []
    for path in file_list:
        try:
            with open(path, "r", encoding=encoding, errors=errors) as fh:
                for line in fh:
                    if regex.search(line):
                        matches.append(path)
                        break
        except OSError:
            continue
    return matches

