        except OSError:
            continue
    return count

def _extract_tree(module, name=""):
    """Recursively extract a JSON-serializable tree from an nn.Module.

    Each node contains the module's name and type, its directly owned
    parameters, its children, and aggregated totals. Tied (shared)
    parameters are flagged and counted only once. Uninitialized lazy
    parameters are flagged as lazy and have no shape. Modules stored in
    plain Python containers (instead of nn.ModuleList / nn.ModuleDict)
    produce a warning.
    """
    import torch.nn as nn
    from torch.nn.parameter import UninitializedParameter, UninitializedBuffer

    seen = set()

    def _is_lazy(p):
        return isinstance(p, (UninitializedParameter, UninitializedBuffer))

    def _find_unregistered(mod):
        found = []
        skip = {"_modules", "_parameters", "_buffers"}
        for attr, value in vars(mod).items():
            if attr in skip:
                continue
            items = None
            if isinstance(value, (list, tuple, set)):
                items = value
            elif isinstance(value, dict):
                items = value.values()
            if items is None:
                continue
            try:
                if any(isinstance(v, nn.Module) for v in items):
                    found.append(attr)
            except Exception:
                continue
        return found

    def _walk(mod, node_name):
        params = []
        total = 0
        trainable = 0
        size_bytes = 0

        for pname, p in mod._parameters.items():
            if p is None:
                continue
            lazy = _is_lazy(p)
            pid = id(p)
            shared = pid in seen
            seen.add(pid)
            if lazy:
                numel = 0
                shape = None
                nbytes = 0
            else:
                numel = int(p.numel())
                shape = [int(s) for s in p.shape]
                nbytes = int(p.numel() * p.element_size())
            requires_grad = bool(p.requires_grad)
            params.append(
                {
                    "name": pname,
                    "shape": shape,
                    "numel": numel,
                    "requires_grad": requires_grad,
                    "dtype": None if lazy else str(p.dtype).replace("torch.", ""),
                    "shared": shared,
                    "lazy": lazy,
                }
            )
            if not shared:
                total += numel
                size_bytes += nbytes
                if requires_grad:
                    trainable += numel

        children = []
        for cname, child in mod._modules.items():
            if child is None:
                continue
            c = _walk(child, cname)
            children.append(c)
            total += c["total_params"]
            trainable += c["trainable_params"]
            size_bytes += c["size_bytes"]

        warnings = []
        for attr in _find_unregistered(mod):
            warnings.append(
                f"Attribute '{attr}' holds nn.Module instances in a plain "
                "Python container; use nn.ModuleList or nn.ModuleDict so "
                "they are registered."
            )

        return {
            "name": node_name,
            "type": type(mod).__name__,
            "params": params,
            "children": children,
            "total_params": total,
            "trainable_params": trainable,
            "size_bytes": size_bytes,
            "has_lazy": any(p["lazy"] for p in params)
            or any(c.get("has_lazy") for c in children),
            "warnings": warnings,
        }

    return _walk(module, name)

def _extract_tree(module, name=""):
    import torch
    from torch import nn
    # Initialize shared‑parameter registry on the function object
    if not hasattr(_extract_tree, "_seen_params"):
        _extract_tree._seen_params = {}
    seen = _extract_tree._seen_params

    # Helper to create a node dictionary
    def make_node(node_name, node_type):
        return {
            "name": node_name,
            "type": node_type,
            "children": [],
            "parameters": [],
        }

    node = make_node(name or module.__class__.__name__, module.__class__.__name__)

    # ----- parameters (non‑recursive) -----
    for param_name, param in module.named_parameters(recurse=False):
        param_id = id(param)
        is_shared = param_id in seen
        seen[param_id] = True  # mark as seen for future occurrences

        is_lazy = isinstance(param, torch.nn.parameter.UninitializedParameter)
        shape = None if is_lazy else list(param.shape)

        param_info = {
            "name": param_name,
            "shape": shape,
            "dtype": str(param.dtype),
            "requires_grad": param.requires_grad,
            "shared": is_shared,
            "lazy": is_lazy,
        }
        node["parameters"].append(param_info)

    # ----- registered sub‑modules (recursive) -----
    for child_name, child_mod in module.named_children():
        child_node = _extract_tree(child_mod, name=child_name)
        node["children"].append(child_node)

    # ----- detect unregistered modules stored in plain containers -----
    # Look at all attributes of the module; if they are nn.Module instances
    # but not present in module._modules, they are unregistered.
    for attr_name, attr_val in vars(module).items():
        if isinstance(attr_val, nn.Module) and attr_name not in module._modules:
            warning_node = make_node(attr_name, attr_val.__class__.__name__)
            warning_node["warning"] = "unregistered module (store in nn.ModuleList/Dict)"
            node["children"].append(warning_node)
        elif isinstance(attr_val, (list, tuple)):
            for idx, item in enumerate(attr_val):
                if isinstance(item, nn.Module):
                    warning_node = make_node(f"{attr_name}[{idx}]", item.__class__.__name__)
                    warning_node["warning"] = "unregistered module inside list/tuple"
                    node["children"].append(warning_node)
        elif isinstance(attr_val, dict):
            for key, item in attr_val.items():
                if isinstance(item, nn.Module):
                    warning_node = make_node(f"{attr_name}[{key}]", item.__class__.__name__)
                    warning_node["warning"] = "unregistered module inside dict"
                    node["children"].append(warning_node)

    return node

def _extract_tree(module, name="", _visited=None):
    import torch.nn as nn
    if _visited is None:
        _visited = {}
    node = {
        "name": name,
        "type": module.__class__.__name__,
        "params": [],
        "children": [],
    }
    # Parameters (non‑recursive)
    for pname, param in module.named_parameters(recurse=False):
        full_name = f"{name}.{pname}" if name else pname
        param_id = id(param)
        shared = param_id in _visited
        if not shared:
            _visited[param_id] = full_name
        # Detect lazy/uninitialized parameters (shape empty)
        lazy = param.shape == torch.Size([])
        shape = list(param.shape) if not lazy else "uninitialized"
        node["params"].append(
            {
                "name": pname,
                "shape": shape,
                "dtype": str(param.dtype),
                "numel": param.numel(),
                "trainable": param.requires_grad,
                "shared": shared,
                "lazy": lazy,
            }
        )
    # Registered children
    for child_name, child_mod in module.named_children():
        child_node = _extract_tree(child_mod, name=child_name, _visited=_visited)
        node["children"].append(child_node)
    # Detect unregistered nn.Module attributes
    warnings = []
    for attr, value in vars(module).items():
        if isinstance(value, nn.Module) and attr not in module._modules:
            warnings.append(
                f"Unregistered submodule '{attr}' found; consider using nn.ModuleList or nn.ModuleDict."
            )
    if warnings:
        node["warnings"] = warnings
    return node

def _extract_tree(module, name=""):
    import torch

    # Track visited modules to avoid infinite recursion on shared module instances
    visited_modules = set()
    # Track parameters to detect shared (tied) parameters
    seen_params = {}
    # Collect warnings about unregistered sub-modules
    warnings = []

    def recurse(mod, mod_name):
        # Prevent infinite loops for the same module instance appearing multiple times
        if id(mod) in visited_modules:
            return {
                "name": mod_name,
                "type": type(mod).__name__,
                "shared_module": True,
                "parameters": [],
                "children": [],
            }
        visited_modules.add(id(mod))

        # Extract parameters directly attached to this module (non‑recursive)
        params = []
        for pname, p in mod.named_parameters(recurse=False):
            pid = id(p)
            shared = pid in seen_params
            if not shared:
                seen_params[pid] = (mod_name, pname)

            # Detect lazy/uninitialized parameters
            if isinstance(p, torch.nn.parameter.UninitializedParameter):
                shape = "uninitialized"
                lazy = True
            else:
                shape = list(p.shape)
                lazy = False

            params.append(
                {
                    "name": pname,
                    "shape": shape,
                    "dtype": str(p.dtype),
                    "requires_grad": p.requires_grad,
                    "shared": shared,
                    "lazy": lazy,
                }
            )

        # Recursively process registered child modules
        children = []
        for child_name, child_mod in mod.named_children():
            children.append(recurse(child_mod, child_name))

        # Detect modules stored in plain attributes (e.g., lists/dicts) that are not registered
        for attr_name, attr_val in vars(mod).items():
            if isinstance(attr_val, torch.nn.Module):
                # Skip if already captured via named_children
                if not any(attr_name == cn for cn, _ in mod.named_children()):
                    warnings.append(
                        f"Unregistered submodule '{attr_name}' in module '{mod_name}'."
                    )
                    children.append(recurse(attr_val, attr_name))

        node = {
            "name": mod_name,
            "type": type(mod).__name__,
            "parameters": params,
            "children": children,
        }
        if warnings:
            node["warnings"] = warnings.copy()
        return node

    root_name = name or type(module).__name__
    return recurse(module, root_name)

