def test_mpax_survives_missing_jax(self):
    import importlib
    import sys

    prefixes = ("jax", "mpax_if", "mpax")
    def _is_target(name):
        return any(name == p or name.startswith(p + ".") for p in prefixes)

    saved = {name: mod for name, mod in sys.modules.items() if _is_target(name)}
    for name in saved:
        del sys.modules[name]

    # Setting an entry to None makes any subsequent `import jax` raise ImportError.
    sys.modules["jax"] = None
    try:
        mod = importlib.import_module("mpax_if")
        self.assertIsNotNone(mod)
    finally:
        for name in list(sys.modules):
            if _is_target(name):
                del sys.modules[name]
        sys.modules.update(saved)
