    if "mpax_if" in sys.modules:
        saved_modules["mpax_if"] = sys.modules.pop("mpax_if")
    try:
        mpax_if = importlib.import_module("mpax_if")
        # Import should succeed even without JAX
        self.assertTrue(True)
        # The module should either not have a jax attribute or have it set to None
        self.assertTrue(not hasattr(mpax_if, "jax") or mpax_if.jax is None)
